function unique(field) { return [...new Set(data.map(r=>r[field]))].sort(); }
function fillSelect(id, field) {
  const sel=document.getElementById(id);
  if(!sel) return;
  unique(field).forEach(v=>{ let o=document.createElement('option'); o.value=v; o.textContent=v; sel.appendChild(o); });
}
function render() {
  const q=document.getElementById('search').value.toLowerCase();
  const stage=document.getElementById('stageFilter').value;
  const risk=document.getElementById('riskFilter').value;
  const owner=document.getElementById('ownerFilter').value;
  const body=document.getElementById('rows');
  body.innerHTML='';
  data.filter(r=>
    (!q || r.Client.toLowerCase().includes(q) || r.Matter_ID.toLowerCase().includes(q)) &&
    (!stage || r.Stage===stage) && (!risk || r.Risk_Level===risk) && (!owner || r.Owner===owner)
  ).forEach(r=>{
    const tr=document.createElement('tr');
    tr.innerHTML=`<td>${r.Matter_ID}</td><td>${r.Client}</td><td>${r.Stage}</td><td>${r.Owner}</td><td>${r.Due_Date}</td><td>${r.Risk_Level}</td><td>${r.Next_Action}</td>`;
    body.appendChild(tr);
  });
  document.getElementById('total').textContent=data.length;
  document.getElementById('overdue').textContent=data.filter(r=>r.Priority==='Urgent').length;
  document.getElementById('review').textContent=data.filter(r=>r.Stage==='5 Review Queue').length;
  document.getElementById('signing').textContent=data.filter(r=>r.Stage==='7 Signing Prep').length;
}
fillSelect('stageFilter','Stage'); fillSelect('ownerFilter','Owner');
document.getElementById('search').addEventListener('input',render);
document.getElementById('stageFilter').addEventListener('change',render);
document.getElementById('riskFilter').addEventListener('change',render);
document.getElementById('ownerFilter').addEventListener('change',render);
document.getElementById('report').textContent=`Friday 4:00 PM Status Report
Total active matters: ${data.length}
Overdue or urgent: ${data.filter(r=>r.Priority==='Urgent').length}
Attorney review queue: ${data.filter(r=>r.Stage==='5 Review Queue').length}
Signing prep: ${data.filter(r=>r.Stage==='7 Signing Prep').length}
High risk: ${data.filter(r=>r.Risk_Level==='High').length}`;
render();
